/// 🧳️ Every partial native owner remains in its original metadata source through cancellation.
pub struct OriginalCommitMetadata{binding:Option<OriginalSourceBinding>,decoder:(u64,u64),store:usize,generation:u64,revision:[u8;32],message:ManuallyDrop<Option<String>>,authors:ManuallyDrop<Option<Vec<Author>>>,pending:OriginalPendingEditIds,ids:ManuallyDrop<Option<Vec<String>>>,change:OriginalHistoryIdentity,hash:OriginalPendingCheckpointIdentity,facts:OriginalCommitFactBirth,pair:ManuallyDrop<Option<(Change,Checkpoint)>>,change_id:ManuallyDrop<Option<String>>,checkpoint_id:ManuallyDrop<Option<String>>,current:ManuallyDrop<Option<String>>,time:ManuallyDrop<Option<String>>,digits:[u8;20],start:usize,parent:Option<ArtifactHistoryKey>,search:Option<ArtifactHistoryKey>,offset:usize,retirement:RetainedCloneClose,phase:u8,closing:bool}
