 /// 🎟️ The exact caller-owned authored allocations move only after the fixed source birth is admitted.
 pub fn admit<P,M>(store:&ArtifactStore<P,M>,message:&mut Option<String>,authors:&mut Vec<Author>,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>where P:ToValue+Send+Sync+'static,M:ToValue+FromValue+Mutation<P>+OpBinary+OpText+Send+'static{let decoder=cx.native_receiving_identity().ok_or_else(||invalid("checkpoint metadata requires its original native decoder"))?;let binding=OriginalSourceBinding::borrow(cx);let d=Self::birth_demands();admit_original_construction(cx,output,construction(d),|_|Ok((Box::new(Self{binding:Some(binding),decoder,store:store as*const _ as usize,generation:store.generation(),revision:store.content_revision(),message:ManuallyDrop::new(message.take()),authors:ManuallyDrop::new(Some(std::mem::take(authors))),pending:Default::default(),ids:ManuallyDrop::new(None),change:Default::default(),hash:Default::default(),facts:Default::default(),pair:ManuallyDrop::new(None),change_id:ManuallyDrop::new(None),checkpoint_id:ManuallyDrop::new(None),current:ManuallyDrop::new(None),time:ManuallyDrop::new(None),digits:[0;20],start:20,parent:None,search:None,offset:0,retirement:Default::default(),phase:0,closing:false}),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})))}
 fn valid<P,M>(&self,store:&ArtifactStore<P,M>,cx:&StepContext<'_>)->bool where P:ToValue+Send+Sync+'static,M:ToValue+FromValue+Mutation<P>+OpBinary+OpText+Send+'static{self.binding.is_some_and(|binding|binding.matches(cx))&&cx.native_receiving_identity()==Some(self.decoder)&&self.store==store as*const _ as usize&&self.generation==store.generation()&&self.revision==store.content_revision()}
 /// 🪡️ Selection, authored hashes and canonical pair construction remain private and independently funded.
 pub fn advance<P,M>(&mut self,store:&ArtifactStore<P,M>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>where P:ToValue+Send+Sync+'static,M:ToValue+FromValue+Mutation<P>+OpBinary+OpText+Send+'static{if self.closing||!self.valid(store,cx){return Err(invalid("checkpoint metadata changed its original source or Store").into())}if self.ready(){return Ok(true)}let log=store.parts_ref().log;let parent=self.parent.map(|key|log.envelope.vcs.checkpoints.get_key(key).ok_or_else(||invalid("checkpoint original parent disappeared"))).transpose()?;match self.phase{
 0=>{let d=self.pending.demands(&log.applied_edit_ids)?;action(cx,d,|g|self.pending.advance(self.generation,&log.applied_edit_ids,&log.envelope.vcs.changes,g,|_|Ok(())))?;if self.pending.ready(){self.phase=1;}},
 1=>{action(cx,fixed(size_of::<Vec<String>>()+128),|g|{let Some((value,p))=self.pending.take(g)?else{return Ok(Default::default())};if value.is_empty(){*self.ids=Some(value);return Err(ValueError::literal(ValueRefusalKind::InvalidValue,semio_framework_os_store_engine_core::lifted_document_materialize::EMPTY_CHECKPOINT_MESSAGE).with_retained_progress(p))}*self.ids=Some(value);self.phase=2;Ok(p)})?;},
 2=>{action(cx,fixed(256),|_|{self.search=log.envelope.vcs.checkpoints.last_key();let mut now=semio_framework_os_store_initialization_runtime::lifted_document_materialize::now_ms();self.start=20;loop{self.start-=1;self.digits[self.start]=b'0'+(now%10)as u8;now/=10;if now==0{break}}self.phase=if log.current_checkpoint_id.is_some(){3}else{4};Ok(RetainedCloneProgress{copied_items:1,copied_bytes:256,..Default::default()})})?;},
 3=>{action(cx,fixed(256),|_|{let key=self.search.ok_or_else(||invalid("checkpoint parent is absent from original history"))?;let row=log.envelope.vcs.checkpoints.get_key(key).ok_or_else(||invalid("checkpoint parent row changed"))?;let current=log.current_checkpoint_id.as_deref().ok_or_else(||invalid("checkpoint original current head disappeared"))?;let end=(self.offset+64).min(current.len());if row.id.len()!=current.len()||row.id.as_bytes()[self.offset..end]!=current.as_bytes()[self.offset..end]{self.search=log.envelope.vcs.checkpoints.previous_key(key);self.offset=0;}else if end==current.len(){self.parent=Some(key);self.offset=0;self.phase=4;}else{self.offset=end;}Ok(RetainedCloneProgress{copied_items:1,copied_bytes:256,..Default::default()})})?;},
 4=>{let source=std::str::from_utf8(&self.digits[self.start..]).map_err(|_|invalid("checkpoint timestamp is not decimal"))?;if text(&mut self.time,source,cx)?{self.phase=5;}},
 5=>{let input=OriginalHistoryIdentityInput::Change{edit_ids:self.ids.as_ref().unwrap(),description:self.message.as_deref()};let d=self.change.demands();action(cx,d,|g|self.change.advance(self.generation,&input,g))?;if self.change.digest().is_some(){self.phase=6;}},
 6=>{if identifier(&mut self.change_id,"change",self.change.digest().unwrap(),cx)?{self.phase=7;}},
 7=>{let input=OriginalPendingCheckpointInput{generation:self.generation,parent:parent.map(|row|row.id.as_str()),prior_change_ids:parent.map_or(&[],|row|row.change_ids.as_slice()),changes:&log.envelope.vcs.changes,pending_id:self.change_id.as_deref().unwrap(),pending_edits:self.ids.as_ref().unwrap(),pending_description:self.message.as_deref(),saved_at:self.time.as_deref().unwrap(),timestamp:self.time.as_deref().unwrap(),message:self.message.as_deref(),authors:self.authors.as_deref().unwrap()};let d=self.hash.demands();action(cx,d,|g|self.hash.advance(&input,g))?;if self.hash.digest().is_some(){self.phase=8;}},
 8=>{if identifier(&mut self.checkpoint_id,"ck",self.hash.digest().unwrap(),cx)?{self.phase=9;}},
 9=>{if text(&mut self.current,self.checkpoint_id.as_deref().unwrap(),cx)?{self.phase=10;}},
 10=>{let input=OriginalCommitFactInput{generation:self.generation,parent,change_id:self.change_id.as_deref().unwrap(),saved_at:self.time.as_deref().unwrap(),timestamp:self.time.as_deref().unwrap()};let d=self.facts.demands(&input)?;action(cx,d,|g|self.facts.advance(&input,&mut self.ids,&mut self.message,self.authors.as_mut().unwrap(),g))?;if self.facts.ready(){self.phase=11;}},
 11=>{let d=OriginalCommitFactBirth::take_demands();action(cx,d,|g|{let Some((mut pair,p))=self.facts.take(g)?else{return Ok(Default::default())};pair.1.id=self.checkpoint_id.take().unwrap();*self.pair=Some(pair);self.phase=12;Ok(p)})?;},
 _=>return Err(invalid("checkpoint metadata phase changed").into()),
 }Ok(self.ready())}
 pub fn ready(&self)->bool{self.phase==12&&!self.closing}
 /// 🤝️ The real canonical pair crosses once without copying its original authored allocations.
 pub fn take(&mut self,cx:&mut StepContext<'_>,output:&mut Option<OriginalCommitMetadataOutput>)->Result<bool,OriginalTurnFailure>{if !self.ready()||!self.binding.is_some_and(|binding|binding.matches(cx))||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid("checkpoint metadata handoff changed its original caller").into())}let d=fixed(2*size_of::<OriginalCommitMetadataOutput>());admit_original_construction(cx,output,construction(d),|_|{let(change,checkpoint)=self.pair.take().unwrap();self.phase=13;Ok((OriginalCommitMetadataOutput{change,checkpoint,current:self.current.take().unwrap()},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})}
 /// 📏️ The first actual child or typed owner determines the cancellation quote.
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.terminal_is_empty(){return Ok(Default::default())}if !self.closing{return Ok(fixed(1))}if !self.pending.terminal_is_empty(){return self.pending.close_demands(body)}if !self.facts.terminal_is_empty(){return self.facts.close_demands(body)}if !self.change.terminal_is_empty(){return Ok(fixed(128))}if !self.hash.terminal_is_empty(){return Ok(fixed(size_of::<Option<(u64,[usize;22])>>()+size_of::<Option<[u8;32]>>()))}if !self.retirement.is_empty(){return self.retirement.demands(body)}
 macro_rules! quote{($field:ident,$ty:ty)=>{if self.$field.is_some(){return self.retirement.next_owner_demands::<$ty>(true,&None,body)}};}quote!(message,String);quote!(authors,Vec<Author>);quote!(ids,Vec<String>);quote!(pair,(Change,Checkpoint));quote!(change_id,String);quote!(checkpoint_id,String);quote!(current,String);quote!(time,String);Ok(fixed(128))}
 /// ♻️ Every partial authored field and hash state returns through the original receiving context.
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.binding.is_some_and(|binding|binding.matches(cx))||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid("checkpoint close changed its original caller").into())}if self.terminal_is_empty(){return Ok(true)}let body=cx.retained_grant().maximum_copy_bytes;let d=self.close_demands(body)?;if !self.closing{close_original_retained_step(cx,d,|_|{self.closing=true;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()}))})?;return Ok(false)}if !self.pending.terminal_is_empty(){close_original_retained_step(cx,d,|g|self.pending.close_step(g))?;}else if !self.facts.terminal_is_empty(){close_original_retained_step(cx,d,|g|self.facts.close_step(g))?;}else if !self.change.terminal_is_empty(){close_original_retained_step(cx,d,|g|Ok(RetainedCloneStep::Progress(self.change.close_step(g))))?;}else if !self.hash.terminal_is_empty(){close_original_retained_step(cx,d,|g|Ok(RetainedCloneStep::Progress(self.hash.close_step(g))))?;}else if !self.retirement.is_empty(){let selection=self.retirement.select(body)?;close_original_retained_step(cx,d,|g|selection.step(g))?;}else{
 macro_rules! close{($field:ident)=>{if self.$field.is_some(){close_original_retained_step(cx,d,|g|Ok(self.retirement.begin_granted(&mut self.$field,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default()))))?;return Ok(false)}};}close!(message);close!(authors);close!(ids);close!(pair);close!(change_id);close!(checkpoint_id);close!(current);close!(time);close_original_retained_step(cx,d,|_|{self.binding=None;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;}Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.message.is_none()&&self.authors.is_none()&&self.pending.terminal_is_empty()&&self.ids.is_none()&&self.change.terminal_is_empty()&&self.hash.terminal_is_empty()&&self.facts.terminal_is_empty()&&self.pair.is_none()&&self.change_id.is_none()&&self.checkpoint_id.is_none()&&self.current.is_none()&&self.time.is_none()&&self.retirement.is_empty()}
